function OverseaChatEmojiCell:FreshUI(data, pageNo, count, pageSize, cb)
    self.cb = cb
    local start = (pageNo - 1) * pageSize
    --print('----->>', #data, start, pageNo, count)
    KTool.DestroyGameObjectChildren(self.GridLayout.gameObject, false)
    for i = 1, count do
        local go = KTool.Instantiate(self.GridLayout.gameObject, self.BtnEmojiNode.gameObject, false)
        KTool.SetActive(go, true)
        local position = i + start
        ---@type GoodsEmojiVo
        local vo = data[position]
        if vo then
            CfUtils.FillImage(go.transform:Find("ImgIcon"), vo.photoPath)
            SetButtonAction(go, function()
                if self.cb then
                    self.cb(position, vo)
                end
            end)
        end
    end
end

function OverseaChatEmojiCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return OverseaChatEmojiCell